    private View named(String s){for(View v:tree())if(v instanceof TextView&&s.equals(((TextView)v).getText().toString()))return v;return null;}
    private Activity open(String view){Intent i=new Intent();i.setClassName(getTargetContext(),"org.zhixiaoce.aperture.CinemaActivity");i.putExtra("view",view);i.addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK);return startActivitySync(i);}
    private boolean ownedFocus()throws Exception{if(activity.hasWindowFocus())return true;try{android.app.Dialog d=(android.app.Dialog)field(activity,"settingsDialog");return d!=null&&d.isShowing()&&d.getWindow().getDecorView().hasWindowFocus();}catch(NoSuchFieldException noDialog){return false;}}
    private void key(int code)throws Exception{until(()->read(()->ownedFocus()),"window focus before key "+code);long now=SystemClock.uptimeMillis();if(!getUiAutomation().injectInputEvent(new KeyEvent(now,now,KeyEvent.ACTION_DOWN,code,0,0,KeyCharacterMap.VIRTUAL_KEYBOARD,0,0,InputDevice.SOURCE_DPAD),true))throw new AssertionError("system key down rejected");if(!getUiAutomation().injectInputEvent(new KeyEvent(now,SystemClock.uptimeMillis(),KeyEvent.ACTION_UP,code,0,0,KeyCharacterMap.VIRTUAL_KEYBOARD,0,0,InputDevice.SOURCE_DPAD),true))throw new AssertionError("system key up rejected");SystemClock.sleep(250);}
