    private boolean playing()throws Exception{return read(()->Boolean.TRUE.equals(field(activity,"prepared"))&&field(activity,"player")!=null&&((MediaPlayer)field(activity,"player")).isPlaying());}
    private void picture(String n)throws Exception{SystemClock.sleep(250);Bitmap b=getUiAutomation().takeScreenshot();if(b==null)throw new IOException("system screenshot unavailable");try(FileOutputStream out=new FileOutputStream(new File(getTargetContext().getFilesDir(),"s79-"+n+".png"))){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();images.put(n);}
