        JSONObject decoded=network(port,fingerprint,"/probe","POST",new JSONObject().put("url",args.getString("fixture")+"/bbb.mp4").put("allowHttp",true),token);check(decoded.getInt("_status")==200&&decoded.optBoolean("firstFrameDecoded")&&Integer.parseInt(decoded.getString("width"))>0,"paired probe decodes a real first frame with native device decoder");
