        check(network(port,fingerprint,"/close","POST",new JSONObject(),token).optBoolean("closed"),"TV connection can be explicitly revoked");SystemClock.sleep(500);boolean denied=false;try{denied=network(port,fingerprint,"/status","GET",null,token).getInt("_status")!=200;}catch(Exception closed){denied=true;}check(denied,"revoked connection cannot read the next request");
